%%\ build_soil_moisture_sim.m
% Construit, configure, simule et exporte automatiquement le modele Simulink
% "Smart_Irrigation_Model" : irrigation intelligente en boucle fermee
% (controleur a hysteresis) avec capteur d'humidite ESP32 bruite.
%
% Unites : temps [h] | flux hydriques [mm/h] | humidite du sol [%]
% Prerequis : MATLAB + Simulink (R2021a+ pour jsonencode 'PrettyPrint',
%             un repli automatique est prevu pour les versions anterieures).
%
% Fichiers produits (dans le dossier de ce script) :
%   - Smart_Irrigation_Model.slx
%   - simulation_irrigation_240h.json   (nom derive de sim_days)

%%\ 0. Parametres generaux et utilitaires
model_name = 'Smart_Irrigation_Model';
sim_days    = 10;                                 % duree de simulation [jours]
stop_time_h = sim_days * 24;                      % 240 h
json_name   = sprintf('simulation_irrigation_%dh.json', stop_time_h);

out_dir = fileparts(mfilename('fullpath'));
if isempty(out_dir), out_dir = pwd; end
slx_path  = fullfile(out_dir, [model_name '.slx']);
json_path = fullfile(out_dir, json_name);

blk  = @(name) [model_name '/' name];                 % chemin complet d'un bloc
pos  = @(x, y, w, h) [x, y, x + w, y + h];            % [gauche haut droite bas]
link = @(src, dst) add_line(model_name, src, dst, 'autorouting', 'smart');

%%\ 1. Fermeture / suppression propre d'une ancienne instance du modele
if bdIsLoaded(model_name)
    set_param(model_name, 'Dirty', 'off');            % evite l'invite d'enregistrement
    close_system(model_name, 0);                      % ferme sans sauvegarder
end
if bdIsLoaded(model_name)                             % securite
    bdclose(model_name);
end

%%\ 2. Creation du modele
new_system(model_name);
open_system(model_name);

%%\ 3. Entrees climatiques
% ET0 = 0.22 mm/h (~5.2 mm/jour) ; ETc = Kc * ET0
add_block('simulink/Sources/Constant', blk('ET0_NASA'), ...
    'Position', pos(40, 200, 70, 30));
set_param(blk('ET0_NASA'), 'Value', '0.22');

add_block('simulink/Math Operations/Gain', blk('Kc'), ...
    'Position', pos(170, 195, 60, 40));
set_param(blk('Kc'), 'Gain', '1.15');

add_block('simulink/Sources/Constant', blk('Pluie'), ...
    'Position', pos(40, 115, 70, 30));
set_param(blk('Pluie'), 'Value', '0');

%%\ 4. Dynamique du sol : bilan hydrique -> mm vers % -> integration
% Bilan [mm/h] = Pluie + Irrigation - ETc
add_block('simulink/Math Operations/Sum', blk('Bilan_Hydrique'), ...
    'Position', pos(300, 110, 40, 80));
set_param(blk('Bilan_Hydrique'), 'Inputs', '++-', 'IconShape', 'rectangular');

% 1 mm d'eau sur Zr = 300 mm de sol  ->  (100/300) % d'humidite par mm
add_block('simulink/Math Operations/Gain', blk('Facteur_Profondeur_Zr'), ...
    'Position', pos(400, 135, 70, 30));
set_param(blk('Facteur_Profondeur_Zr'), 'Gain', '100/300');

% Humidite reelle du sol [%], saturee entre 10 % (sec) et 45 % (sature)
add_block('simulink/Continuous/Integrator', blk('Humidite_Sol_Reelle'), ...
    'Position', pos(530, 125, 50, 50));
set_param(blk('Humidite_Sol_Reelle'), ...
    'InitialCondition',     '28', ...
    'LimitOutput',          'on', ...
    'UpperSaturationLimit', '45', ...
    'LowerSaturationLimit', '10');

%%\ 5. Capteur physique ESP32 : bruit de mesure ADC
add_block('simulink/Sources/Band-Limited White Noise', blk('Bruit_ADC_ESP32'), ...
    'Position', pos(570, 210, 90, 40));
set_param(blk('Bruit_ADC_ESP32'), ...
    'Cov',  '0.05', ...
    'Ts',   '0.1', ...
    'seed', '23341');                                 % graine fixe : resultats reproductibles

add_block('simulink/Math Operations/Sum', blk('Add_Noise'), ...
    'Position', pos(700, 120, 30, 60));
set_param(blk('Add_Noise'), 'Inputs', '++', 'IconShape', 'rectangular');

%%\ 6. Controleur d'irrigation a hysteresis (boucle fermee)
% Relais "on"  quand humidite > 35 %  -> sortie 0    mm/h (arret)
% Relais "off" quand humidite < 22 %  -> sortie 5    mm/h (irrigation)
add_block('simulink/Discontinuities/Relay', blk('Controleur_Irrigation'), ...
    'Position', pos(760, 300, 70, 50));
set_param(blk('Controleur_Irrigation'), ...
    'OnSwitchValue',  '35', ...
    'OffSwitchValue', '22', ...
    'OnOutputValue',  '0', ...
    'OffOutputValue', '5');

%%\ 7. Visualisation et enregistrement
add_block('simulink/Sinks/Scope', blk('Scope'), ...
    'Position', pos(900, 140, 50, 60));
set_param(blk('Scope'), 'NumInputPorts', '2');

add_block('simulink/Sinks/To Workspace', blk('WS_Humidite_Capteur'), ...
    'Position', pos(900, 80, 100, 30));
set_param(blk('WS_Humidite_Capteur'), ...
    'VariableName', 'sensor_soil_moisture_pct', ...
    'SaveFormat',   'Timeseries', ...
    'SampleTime',   '-1');

add_block('simulink/Sinks/To Workspace', blk('WS_Irrigation'), ...
    'Position', pos(900, 380, 100, 30));
set_param(blk('WS_Irrigation'), ...
    'VariableName', 'irrigation_cmd_mm_h', ...
    'SaveFormat',   'Timeseries', ...
    'SampleTime',   '-1');

%%\ 8. Connexions
link('ET0_NASA/1',              'Kc/1');
link('Pluie/1',                 'Bilan_Hydrique/1');          % (+) pluie
link('Controleur_Irrigation/1', 'Bilan_Hydrique/2');          % (+) irrigation
link('Kc/1',                    'Bilan_Hydrique/3');          % (-) ETc
link('Bilan_Hydrique/1',        'Facteur_Profondeur_Zr/1');
link('Facteur_Profondeur_Zr/1', 'Humidite_Sol_Reelle/1');
link('Humidite_Sol_Reelle/1',   'Add_Noise/1');
link('Bruit_ADC_ESP32/1',       'Add_Noise/2');
link('Add_Noise/1',             'Controleur_Irrigation/1');    % mesure -> controleur
link('Add_Noise/1',             'Scope/1');
link('Add_Noise/1',             'WS_Humidite_Capteur/1');
link('Controleur_Irrigation/1', 'Scope/2');
link('Controleur_Irrigation/1', 'WS_Irrigation/1');

% Nommage des signaux (se propage a toutes les branches de la meme sortie)
ph = get_param(blk('Add_Noise'), 'PortHandles');
set_param(ph.Outport(1), 'Name', 'sensor_soil_moisture_pct');
ph = get_param(blk('Controleur_Irrigation'), 'PortHandles');
set_param(ph.Outport(1), 'Name', 'irrigation_cmd_mm_h');

%%\ 9. Configuration de la simulation
set_param(model_name, ...
    'SolverType',             'Variable-step', ...
    'Solver',                 'ode45', ...
    'StartTime',              '0', ...
    'StopTime',               num2str(stop_time_h), ...   % '240' = 10 jours
    'MaxStep',                '0.1', ...
    'ReturnWorkspaceOutputs', 'on');

%%\ 10. Mise en page automatique (la disposition manuelle sert de repli)
try
    Simulink.BlockDiagram.arrangeSystem(model_name);
catch ME
    warning('arrangeSystem indisponible (%s) : disposition manuelle conservee.', ME.message);
end

save_system(model_name, slx_path);
fprintf('Modele enregistre : %s\n', slx_path); %[output:76a6f9d7]

%%\ 11. Simulation
simOut = sim(model_name);

%%\ 12. Extraction des Timeseries
ts_hum = simOut.get('sensor_soil_moisture_pct');
ts_irr = simOut.get('irrigation_cmd_mm_h');
assert(isa(ts_hum, 'timeseries') && isa(ts_irr, 'timeseries'), ...
    'Variables To Workspace introuvables dans simOut.');

t   = ts_hum.Time(:);
hum = squeeze(ts_hum.Data); hum = hum(:);
irr = squeeze(ts_irr.Data); irr = irr(:);

% Securite : si les grilles temporelles different, on re-echantillonne
% la commande d'irrigation (maintien d'ordre zero) sur celle de l'humidite.
t_irr = ts_irr.Time(:);
if ~isequal(t_irr, t)
    [tu, iu] = unique(t_irr, 'last');
    irr = interp1(tu, irr(iu), t, 'previous', 'extrap');
end

%%\ 13. Structure MATLAB
meta = struct( ...
    'model',        model_name, ...
    'generated_at', datestr(now, 'yyyy-mm-ddTHH:MM:SS'), ...
    'stop_time_h',  str2double(get_param(model_name, 'StopTime')), ...
    'n_samples',    numel(t), ...
    'units',        struct('time_h', 'h', ...
                           'sensor_soil_moisture_pct', '%', ...
                           'irrigation_cmd_mm_h', 'mm/h'));

summary = struct( ...
    'moisture_min_pct',     min(hum), ...
    'moisture_max_pct',     max(hum), ...
    'moisture_final_pct',   hum(end), ...
    'irrigation_total_mm',  trapz(t, irr), ...
    'irrigation_on_time_h', trapz(t, double(irr > 0)));

export_data = struct( ...
    'metadata',                 meta, ...
    'summary',                  summary, ...
    'time_h',                   t, ...
    'sensor_soil_moisture_pct', hum, ...
    'irrigation_cmd_mm_h',      irr);

%%\ 14. Export JSON
try
    json_txt = jsonencode(export_data, 'PrettyPrint', true);
catch
    json_txt = jsonencode(export_data);               % MATLAB < R2021a (sans mise en forme)
end

fid = fopen(json_path, 'w', 'n', 'UTF-8');
if fid == -1
    error('Impossible d''ecrire le fichier : %s', json_path);
end
fprintf(fid, '%s', json_txt);
fclose(fid);

fprintf('Export JSON       : %s\n', json_path); %[output:1f1da58a]
fprintf('Humidite mesuree  : min %.2f %% | max %.2f %% | finale %.2f %%\n', ... %[output:group:86d3e6cd] %[output:96f9338a]
    summary.moisture_min_pct, summary.moisture_max_pct, summary.moisture_final_pct); %[output:group:86d3e6cd] %[output:96f9338a]
fprintf('Irrigation totale : %.2f mm sur %.2f h d''arrosage\n', ... %[output:group:8195d9f4] %[output:75331382]
    summary.irrigation_total_mm, summary.irrigation_on_time_h); %[output:group:8195d9f4] %[output:75331382]

%%\ 15. Ouverture du Scope (facultatif, ignore en mode sans affichage)
try %[output:group:98a51ecd]
    open_system(blk('Scope')); %[output:1c0baeb7]
catch
end %[output:group:98a51ecd]
open(json_path) %[output:436c8d63]

